Item.method_code:
const { getState, getActions } = options;
const { defaultLanguageCode } = getState();
const actions = getActions();

const label = aras.getResource('', 'toc_editor.new_category');
const relatedItemProps = {
	label,
	[`label@aras.lang.${defaultLanguageCode}`]: label,
	'@odata.type': '#CommandBarMenu'
};
const relatedItem = actions.addRelatedItem(relatedItemProps);

const worldRole = {
	id: 'A73B655731924CD0B027E4F4D5FCC0A9',
	keyedName: 'World'
};
const relationshipItemProps = {
	related_id: relatedItem.id,
	'role@aras.id': worldRole.id,
	'role@aras.keyed_name': worldRole.keyedName
};
const relationshipItem = actions.addRelationshipItem(relationshipItemProps);

actions.selectItem(relationshipItem.id);
